1063	    \begin{lemma}\label{lem:qld-sublines}
1064	      There exists a distribution $D$ over tuples $(\line, \line_X, \line_Z)$ with the following properties:
1065	      \begin{enumerate}
1066	      \item The marginal distribution over $\line$ is the same as the marginal of the line-point distribution over $\F_q^{2m+2}$.
1067	\item For any point of the form $u = (u_X, u_Z, \alpha, \beta)$ lying on $\line$, it holds that $u_X \in \line_X$ and $u_Z \in \line_Z$. Moreover, for $u$ chosen uniformly at random in $\line$ the marginal distribution over $(\line_X,\line_Z, u_X)$ (resp.\ over $(\line_X,\line_Z, u_Z)$) is such that the marginal over $(\ell_X,\ell_Z)$ is a mixture of $D_{\ALine, i}\times D_{\ALine, j}$ and $D_{\DLine, i}\times D_{\DLine, j}$ for $i,j\in\{1,\ldots,m\}$ and moreover, conditioned on $(\ell_X,\ell_Z)$, $u_X$ is uniformly random on $\line_X$ (resp. $u_Z$ uniformly random on $\line_Z$). 
1068	\end{enumerate}
1069	    \end{lemma}
