1129	\[ \hat{Q}^\line_f = \E_{(\line_X, \line_Z) \sim D_{|\line}} \sum_{\substack{f_X \in \deg_{md}(\line_X), f_Z \in \deg_{md}(\line_Z):\\ f = \combine_{f_X, f_Z}}} T^{\line_X, \line_Z}_{f_X, f_Z}\;, \]
